/* Explicit batch decision; no render until user chooses it. */
(()=>{
  const overlay=document.createElement('section');overlay.id='abrxs-batch';overlay.hidden=true;overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Preparar cortes');
  overlay.innerHTML='<div class="batch-panel"><small>IMPORTAR DECISIONES</small><h2>¿Cómo quieres crear estos cortes?</h2><p id="batch-file"></p><label>Resultado<select id="batch-action"><option value="cards">Solo fichas · revisar sin exportar</option><option value="export">Crear fichas y exportar todo el lote</option></select></label><label>Método de corte<select id="batch-method"><option value="preferred">Una versión por corte · verificado o timestamps</option><option value="all">Conservar también alternativas alineadas por texto</option></select></label><label class="batch-check"><input id="batch-dual" type="checkbox"> Usar máster horizontal y/o vertical en este lote</label><div id="batch-masters" hidden><p>Los tiempos del editorial deben pertenecer a la misma grabación. No se detecta ni se sincroniza automáticamente otra edición.</p><div class="batch-master"><label>Máster horizontal<input id="batch-horizontal" readonly placeholder="Sin seleccionar"></label><button data-pick="horizontal">Seleccionar</button><label>Desfase en segundos<input id="batch-horizontal-offset" type="number" step="0.001" value="0"></label></div><div class="batch-master"><label>Máster vertical<input id="batch-vertical" readonly placeholder="Sin seleccionar"></label><button data-pick="vertical">Seleccionar</button><label>Desfase en segundos<input id="batch-vertical-offset" type="number" step="0.001" value="0"></label></div><label>Si un corte no indica formato<select id="batch-unassigned"><option value="ask">Detener y pedir formato</option><option value="both">Ambos másteres seleccionados</option><option value="horizontal">Solo horizontal</option><option value="vertical">Solo vertical</option></select></label><label class="batch-check"><input id="batch-synced" type="checkbox"> Confirmo que son la misma grabación con tiempos equivalentes o el desfase indicado</label><p>JSON: outputs: ["horizontal", "vertical"]. TXT/HTML: tipo horizontal, vertical o intro (ambos). Desfase +2 significa que el instante 10 del editorial se busca en el segundo 12 de ese máster.</p></div><p id="batch-error" role="alert"></p><div class="batch-buttons"><button id="batch-cancel">Cancelar</button><button id="batch-accept">Continuar</button></div></div>';
  document.body.append(overlay);const $=id=>document.getElementById('batch-'+id);let pending=null,key='',previousFocus=null;
  $('dual').onchange=()=>{$('masters').hidden=!$('dual').checked;};
  function close(value){overlay.hidden=true;const resolve=pending;pending=null;previousFocus?.focus();resolve?.(value);}
  $('cancel').onclick=()=>close(null);
  overlay.addEventListener('keydown',e=>{if(e.key==='Escape')close(null);if(e.key==='Tab'){const inputs=[...overlay.querySelectorAll('button,input,select')].filter(n=>!n.disabled&&!n.closest('[hidden]'));const first=inputs[0],last=inputs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  overlay.querySelectorAll('[data-pick]').forEach(b=>b.onclick=async()=>{try{const file=await window.__TAURI__.dialog.open({multiple:false,filters:[{name:'Máster',extensions:['mp4','mov','m4v','mkv']}]});if(file)$(b.dataset.pick).value=file;}catch(e){$('error').textContent=String(e);}});
  $('accept').onclick=()=>{
    const plan={exportAfterImport:$('action').value==='export',cutMethod:$('method').value};
    if($('dual').checked){plan.masters=['horizontal','vertical'].filter(o=>$(o).value).map(o=>({orientation:o,video:$(o).value,offset:Number($(o+'-offset').value)}));if(!plan.masters.length||plan.masters.some(m=>!Number.isFinite(m.offset))){$('error').textContent='Selecciona al menos un máster y desfases válidos.';return;}if(!$('synced').checked){$('error').textContent='Confirma la correspondencia de tiempos antes de continuar.';return;}plan.sameTimelineConfirmed=true;plan.unassignedOutputs=$('unassigned').value;}
    try{localStorage.setItem(key,JSON.stringify({horizontal:$('horizontal').value,vertical:$('vertical').value,horizontalOffset:$('horizontal-offset').value,verticalOffset:$('vertical-offset').value}));}catch{}
    close(plan);
  };
  window.AbrxsBatch={plan(editorial){if(pending)return Promise.reject(Error('Ya hay una elección de cortes abierta.'));key='abrxs-batch-masters:'+state.project?.path;previousFocus=document.activeElement;$('file').textContent=basename(editorial);$('error').textContent='';$('action').value='cards';$('synced').checked=false;$('dual').checked=false;$('masters').hidden=true;$('horizontal').value='';$('vertical').value='';$('horizontal-offset').value='0';$('vertical-offset').value='0';try{const p=JSON.parse(localStorage.getItem(key)||'{}');$('horizontal').value=p.horizontal||'';$('vertical').value=p.vertical||'';$('horizontal-offset').value=p.horizontalOffset||'0';$('vertical-offset').value=p.verticalOffset||'0';}catch{}overlay.hidden=false;$('action').focus();return new Promise(resolve=>pending=resolve);}};
})();
